xpath.script:
(function () {
    function ensureBunnaLogo() {
        const brands = document.querySelectorAll(".navbar-brand, .o_header_standard_logo, a.logo");
        brands.forEach(function (brandLink) {
            let img = brandLink.querySelector("img");
            if (!img) {
                brandLink.innerHTML = '';
                img = document.createElement("img");
                img.src = "/bunna_custom_web_page/static/src/img/bunna_logo.png";
                img.alt = "Bunna Bank Logo";
                img.className = "img-fluid";
                img.style.maxHeight = "44px";
                img.style.width = "auto";
                img.style.objectFit = "contain";
                brandLink.appendChild(img);
            } else if (!img.src.includes("bunna_logo.png")) {
                img.src = "/bunna_custom_web_page/static/src/img/bunna_logo.png";
                img.style.maxHeight = "44px";
                img.style.width = "auto";
                img.style.objectFit = "contain";
            }
        });
    }

    function ensureSingleJobMenu() {
        ensureBunnaLogo();
        const topMenu = document.getElementById("top_menu") || document.querySelector(".navbar-nav");
        if (!topMenu) return;

        const allItems = Array.from(topMenu.querySelectorAll("li.nav-item"));
        const jobItems = allItems.filter(function(li) {
            const link = li.querySelector("a");
            if (!link) return false;
            const text = link.textContent.trim().toLowerCase();
            const href = (link.getAttribute("href") || "").toLowerCase();
            return text === "job" || text === "jobs" || href === "/jobs" || href.startsWith("/jobs");
        });

        if (jobItems.length === 0) {
            const homeItem = allItems.find(function(li) {
                const link = li.querySelector("a");
                return link && (link.textContent.trim().toLowerCase() === "home" || link.getAttribute("href") === "/");
            });
            const jobLi = document.createElement("li");
            jobLi.className = "nav-item";
            jobLi.role = "presentation";
            jobLi.innerHTML = '<a role="menuitem" href="/jobs" class="nav-link"><span>Job</span></a>';
            if (homeItem && homeItem.nextElementSibling) {
                topMenu.insertBefore(jobLi, homeItem.nextElementSibling);
            } else {
                topMenu.appendChild(jobLi);
            }
        } else if (jobItems.length > 1) {
            const firstLink = jobItems[0].querySelector("a");
            if (firstLink) {
                const span = firstLink.querySelector("span") || firstLink;
                span.textContent = "Job";
            }
            for (let i = 1; i < jobItems.length; i++) {
                jobItems[i].remove();
            }
        } else {
            const link = jobItems[0].querySelector("a");
            if (link) {
                const span = link.querySelector("span") || link;
                span.textContent = "Job";
            }
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function() {
            ensureBunnaLogo();
            ensureSingleJobMenu();
        });
    } else {
        ensureBunnaLogo();
        ensureSingleJobMenu();
    }
})();

template.script:
(function() {
    document.documentElement.style.overflow = 'hidden';
    document.body.style.overflow = 'hidden';
    var wrapwrap = document.getElementById('wrapwrap');
    if (wrapwrap) {
        wrapwrap.style.height = '100vh';
        wrapwrap.style.maxHeight = '100vh';
        wrapwrap.style.overflow = 'hidden';
    }
})();
